inputs.common/treaty_articles/00_alliance.txt:
alliance = {
	kind = mutual
	cost = 150

	relations_progress_per_day = 1.5
	relations_improvement_max = 80

	max_target_involvement = 3000
	target_involvement_applies_to = mutual

	icon = "gfx/interface/icons/diplomatic_treaties_articles_icons/alliance_treaties.dds"

	flags = {
		is_alliance
		can_be_renegotiated
		is_military_access
		friendly
	}

	usage_limit = once_per_treaty

	mutual_exclusions = {
		alliance
		defensive_pact
		guarantee_independence
	}

	unlocked_by_technologies = {
		international_relations
	}

	mutual_modifier = {
		country_treaty_leverage_generation_add = 400
	}

	visible = {
	}

	possible = {
		scope:other_country = {
			save_temporary_scope_as = target_country
		}
		custom_tooltip = {
			text = DIPLO_ACTION_RELATIONS_AMICABLE_OR_GREATER
			scope:target_country.relations:root >= relations_threshold:amicable
		}
		highest_overlapping_interest_tier = { target = scope:target_country value >= interest_tier_effect_can_sign_alliance_min_tier }
	}

	requirement_to_maintain = {
		trigger = {
			scope:first_country = {
				NOT = { has_subject_relation_with = scope:second_country }
			}
		}
	}

	requirement_to_maintain = {
		trigger = {
			custom_tooltip = {
				text = "DIPLOMATIC_PACT_REQUIREMENT_DIPLOMATIC_AUTONOMY"
				scope:first_country = { aggressive_diplomatic_plays_permitted = yes }
				scope:second_country = { aggressive_diplomatic_plays_permitted = yes }
			}
		}
	}

	can_ratify = {
		custom_tooltip = {
			text = "alliance_multilateral_alliances_first_country_tt"
			OR = {
				scope:first_country = {
					has_technology_researched = multilateral_alliances
				}
				NOT = {
					scope:first_country = {
						any_scope_treaty = {
							hidden_trigger = {
								OR = {
									scope:treaty = {
										is_renegotiation = no
									}
									scope:treaty.amended_treaty != this
								}
							}
							any_scope_article = {
								has_type = alliance
							}
						}
					}
				}
			}
		}
		custom_tooltip = {
			text = "alliance_multilateral_alliances_second_country_tt"
			OR = {
				scope:second_country = {
					has_technology_researched = multilateral_alliances
				}
				NOT = {
					scope:second_country = {
						any_scope_treaty = {
							hidden_trigger = {
								OR = {
									scope:treaty = {
										is_renegotiation = no
									}
									scope:treaty.amended_treaty != this
								}
							}
							any_scope_article = {
								has_type = alliance
							}
						}
					}
				}
			}
		}

		scope:first_country = {
			NOR = {
				custom_description = {
					text = has_treaty_alliance_with_trigger
					subject = this
					object = scope:second_country

					any_scope_treaty = {
						binds = scope:second_country
						hidden_trigger = {
							OR = {
								scope:treaty = {
									is_renegotiation = no
								}
								scope:treaty.amended_treaty != this
							}
						}
						any_scope_article = {
							has_type = alliance
						}
					}
				}

				custom_description = {
					text = has_treaty_defensive_pact_with_trigger
					subject = this # Country
					object = scope:second_country # Country

					any_scope_treaty = {
						binds = scope:second_country
						hidden_trigger = {
							OR = {
								scope:treaty = {
									is_renegotiation = no
								}
								scope:treaty.amended_treaty != this
							}
						}
						any_scope_article = {
							has_type = defensive_pact
						}
					}
				}
			}
		}

		# ensure neither scope:first_country nor scope:second_country is supporting independence of a subject of the other
		AND = {
			scope:first_country = {
				custom_tooltip = {
					text = "alliance_support_independence_subject"
					NOT = {
						any_subject_or_below = {
							any_scope_treaty = {
								binds = scope:second_country
								any_scope_article = {
									has_type = support_independence
								}
							}
						}
					}
				}
			}

			scope:second_country = {
				custom_tooltip = {
					text = "alliance_support_independence_subject"
					NOT = {
						any_subject_or_below = {
							any_scope_treaty = {
								binds = scope:first_country
								any_scope_article = {
									has_type = support_independence
								}
							}
						}
					}
				}
			}
		}
	}

	on_entry_into_force = {
		if = {
			limit = {
				scope:article_options.second_country = {
					any_scope_treaty = {
						binds = scope:article_options.first_country
						any_scope_article = {
							has_type = defensive_pact
						}
					}
				}
			}

			scope:article_options.first_country = {
				add_lobby_appeasement_from_diplomacy_bidirectional = {
					FIRST = scope:article_options.first_country
					SECOND = scope:article_options.second_country
					PRO_AMOUNT = 1
					ANTI_AMOUNT = -1
					FACTOR = appeasement_alliance_formed
				}
			}
		}
		else = {
			scope:article_options.first_country = {
				add_lobby_appeasement_from_diplomacy_bidirectional = {
					FIRST = scope:article_options.first_country
					SECOND = scope:article_options.second_country
					PRO_AMOUNT = 4
					ANTI_AMOUNT = -4
					FACTOR = appeasement_alliance_formed
				}
			}
		}
	}

	on_withdrawal = {
		scope:withdrawing_country = {
			create_bidirectional_truce = { country = scope:non_withdrawing_country months = 12 }
		}
		add_lobby_appeasement_from_diplomacy_bidirectional = {
			FIRST = scope:withdrawing_country
			SECOND = scope:non_withdrawing_country
			PRO_AMOUNT = -4
			ANTI_AMOUNT = 4
			FACTOR = appeasement_alliance_broken
		}
	}
	on_break = {
		scope:withdrawing_country = {
			change_relations = {
				country = scope:non_withdrawing_country
					value = {
						add = -10
						multiply = {
							value = scope:treaty_options.remaining_binding_period
							min = 365
							divide = 365
						}
						max = -10
						min = -80
					}
			}
			change_infamy = {
				value = {
					add = 3
					multiply = {
						value = scope:treaty_options.remaining_binding_period
						min = 365
						divide = 365
					}
					max = 50
					min = 10
				}
			}
		}
	}

	ai = {

		treaty_categories = {
			military_defense
		}

		evaluation_chance = {
			value = 0.1

			add = {
				value = country_rank
				multiply = 0.05
			}

			if =  {
				limit = {
					num_alliances < 1
					country_rank >= rank_value:major_power
				}
				multiply = 2
			}
			else_if =  {
				limit = {
					num_alliances >= 2
				}
				multiply = 0
			}
		}

		proposal_weight = {
			value = 1

			if = {
				limit = {
					ai_is_regional_objective_protect_target = { TARGET = scope:other_country }
				}
				add = 3
			}

			if =  {
				limit = {
					num_alliances < 1
					country_rank >= rank_value:major_power
				}
				add = 2

				if = {
					limit = { country_rank >= rank_value:great_power }
					add = 2
				}
			}
			else_if =  {
				limit = {
					num_alliances >= 2
				}
				multiply = 0
			}
		}

		article_ai_usage = {
            offer
        }

		inherent_accept_score = {
			value = 0

			# We are doing this to be able to reuse loc across treaties and diplomatic actions
			save_temporary_scope_as = target
			scope:other_country = {
				save_temporary_scope_as = actor
			}

			if = {
				limit = {
					ai_is_regional_objective_protect_target = { TARGET = scope:other_country }
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_REGIONAL_OBJECTIVE_PROTECT"
					value = 25
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_BASE_ADDITIONAL"
				value = -10
			}

			if = {
				limit = {
					has_strategic_adjacency = scope:other_country
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_NEIGHBORS"
					value = 10
				}
			}

			if = {
				limit = {
					OR = {
						is_country_type = recognized
						country_is_colonial_or_company = yes
					}
					scope:other_country = {
						is_country_type = unrecognized
					}
				}
				add = {
					desc = "concept_unrecognized_power_short"
					value = -200
				}
			}

			if = {
				limit = {
					has_strategy = ai_strategy_armed_isolationism
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ISOLATIONIST"
					add = -40
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"
				value = "scope:other_country.ai_army_comparison(root)"
				add = 0.25
				multiply = 25
				min = -200
				max = 50
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
				if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:other_country
								attitude = antagonistic
							}
							has_attitude = {
								who = scope:other_country
								attitude = domineering
							}
							has_attitude = {
								who = scope:other_country
								attitude = belligerent
							}
							has_attitude = {
								who = scope:other_country
								attitude = rebellious
							}
						}
					}
					value = -1000
				}
				else_if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:other_country
								attitude = wary
							}
							has_attitude = {
								who = scope:other_country
								attitude = disinterested
							}
						}
					}
					value = -100
				}
				else_if = {
					limit = {
						has_attitude = {
							who = scope:other_country
							attitude = cautious
						}
					}
					value = -50
				}
			}

			if = {
				limit = {
					"num_alliances_and_defensive_pacts_with_rivals(scope:other_country)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ALLIED_TO_RIVALS"
					value = "num_alliances_and_defensive_pacts_with_rivals(scope:other_country)"
					multiply = -25
				}
			}

			if = {
				limit = {
					"num_alliances_and_defensive_pacts_with_allies(scope:other_country)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ALLIED_TO_ALLIES"
					value = "num_alliances_and_defensive_pacts_with_allies(scope:other_country)"
					multiply = 10
				}
			}

			if = {
				limit = {
					"num_shared_rivals(scope:other_country)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_SHARED_RIVALS"
					value = "num_shared_rivals(scope:other_country)"
					multiply = 10
					max = 30
				}
			}

			if = {
				limit = {
					NOT = {
						any_scope_treaty = {
							binds = scope:other_country
							any_scope_article = {
								has_type = alliance
							}
						}
					}
					any_scope_treaty = {
						count > 0
						any_scope_article = {
							has_type = alliance
						}
					}
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_NUM_ALLIES"
					value = {
						every_scope_treaty = {
							limit = {
								any_scope_article = {
									has_type = alliance
						 		}
							}
							add = 1
						}
					}
					multiply = -20
				}
			}

			if = {
				limit = {
					exists = power_bloc
					exists = scope:other_country.power_bloc
				}
				if = {
					limit = {
						power_bloc = scope:other_country.power_bloc
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_SAME_POWER_BLOC"
						value = 15
					}
				}
				else_if = {
					limit = {
						is_power_bloc_leader = no
						scope:other_country = { is_power_bloc_leader = no }
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_DIFFERENT_POWER_BLOC"
						value = -25
					}
				}
			}

			# Special anti-Opium Wars cheese - block any alliance/defensive pact/guarantee deals before the JE fires
			if = {
				limit = {
					ai_opium_dealer_no_alliance_trigger = yes
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_OPIUM_DEALER"
					add = -1000
				}
			}
		}

		contextual_accept_score = {
			if = {
				limit = {
					scope:treaty ?= {
						NOT = {
							any_scope_article_option = {
								NOT = { has_type = alliance }
								NOT = { is_desired_by = root }
							}
						}
						any_scope_article_option = {
							has_type = alliance
						}
					}
				}
				if = {
					limit = {
						scope:other_country = {
							has_variable = pro_lobby_proposal_alliance
							var:pro_lobby_opportunity_target ?= root
						}
					}
					add = {
						desc = "LOBBY_OPPORTUNITY_BONUS"
						value = 50
					}
				}

				if = {
					limit = {
						scope:other_country = {
							has_variable = anti_lobby_proposal_alliance
							var:anti_lobby_opportunity_target ?= root
						}
					}
					add = {
						desc = "LOBBY_OPPORTUNITY_BONUS"
						value = 25
					}
				}
			}
			else = {
				if = {
					limit = {
						scope:other_country = {
							has_variable = pro_lobby_proposal_alliance
							var:pro_lobby_opportunity_target ?= root
						}
					}
					add = {
						desc = "LOBBY_OPPORTUNITY_BONUS"
						value = 10
					}
				}

				if = {
					limit = {
						scope:other_country = {
							has_variable = anti_lobby_proposal_alliance
							var:anti_lobby_opportunity_target ?= root
						}
					}
					add = {
						desc = "LOBBY_OPPORTUNITY_BONUS"
						value = 5
					}
				}
			}

			if = {
				limit = {
					NOT = { exists = scope:is_treaty_active }
					scope:treaty.binding_period >= 1825
				}
				subtract = {
					desc = "DIPLOMATIC_ACCEPTANCE_BINDING_PERIOD"
					value = scope:treaty.binding_period
					divide = 3650
					subtract = 25
					max = 50
				}
			}
		}
	}
}

