							has_attitude = {
								who = scope:other_country
								attitude = antagonistic
							}
							has_attitude = {
								who = scope:other_country
								attitude = domineering
							}
							has_attitude = {
								who = scope:other_country
								attitude = belligerent
							}
							has_attitude = {
								who = scope:other_country
								attitude = rebellious
							}
						}
					}
					value = -1000
				}
				else_if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:other_country
								attitude = wary
							}
							has_attitude = {
								who = scope:other_country
								attitude = disinterested
							}
						}
					}
					value = -100
				}
				else_if = {
					limit = {
						has_attitude = {
							who = scope:other_country
							attitude = cautious
						}
					}
					value = -50
				}
			}

			if = {
				limit = {
					"num_alliances_and_defensive_pacts_with_rivals(scope:other_country)" > 0
				}
