		evaluation_chance = {
			value = 0.1

			add = {
				value = country_rank
				multiply = 0.05
			}

			# Rebellious subjects should very actively seek fellow subjects to rebel together with
			if = {
				limit = {
					is_subject = yes
					has_attitude = {
						who = overlord
						attitude = rebellious
					}
				}
				add = 1.0
			}
		}

		article_ai_usage = {
            offer
            request
        }

		inherent_accept_score = {
			value = 0

			if = {
				limit = {
					scope:source_country ?= this
				}

				# We are doing this to be able to reuse loc across treaties and diplomatic actions
				scope:source_country = {
					save_temporary_scope_as = target
				}
				scope:target_country = {
					save_temporary_scope_as = actor
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_BASE_ADDITIONAL"
					value = -20
				}

				if = {
					limit = {
						scope:target_country = {
							is_subject = yes
							overlord = scope:source_country.overlord
						}
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_FELLOW_SUBJECT"
						value = 50
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"
					value = "scope:source_country.ai_army_comparison(scope:target_country)"
					multiply = -3
					min = -50
					max = 50
				}

				if = {
					limit = {
						NOT = { is_country_type = unrecognized }
						scope:target_country = { is_country_type = unrecognized }
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_UNRECOGNIZED"
						value = -25
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
					if = {
						limit = {
							has_attitude = {
								who = scope:target_country
								attitude = protective
							}
						}
						value = 25
					}
					if = {
						limit = {
							OR = {
								has_attitude = {
									who = scope:target_country
									attitude = antagonistic
								}
								has_attitude = {
									who = scope:target_country
									attitude = belligerent
								}
								has_attitude = {
									who = scope:target_country
									attitude = rebellious
								}
							}
						}
						value = -1000
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE_TOWARDS_ACTOR_OVERLORD"
					if = {
						limit = {
							OR = {
								has_attitude = {
									who = scope:target_country.overlord
									attitude = antagonistic
								}
								has_attitude = {
									who = scope:target_country.overlord
									attitude = rebellious
								}
							}
						}
						value = 50
					}
					else_if = {
						limit = {
							OR = {
								has_attitude = {
									who = scope:target_country.overlord
									attitude = belligerent
								}
								has_attitude = {
									who = scope:target_country.overlord
									attitude = domineering
								}
								has_attitude = {
									who = scope:target_country.overlord
									attitude = defiant
								}
							}
						}
						value = 30
					}
					else = {
						value = -500
					}
				}
			}
			else = {
				scope:source_country = {
					save_temporary_scope_as = actor
				}
				scope:target_country = {
					save_temporary_scope_as = target
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_BASE_ADDITIONAL"
					value = -10
				}

				if = {
					limit = {
						scope:source_country = {
							is_subject = yes
							overlord = scope:target_country.overlord
						}
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_FELLOW_SUBJECT"
						value = 25
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"
					value = "scope:source_country.ai_army_comparison(scope:target_country)"
					multiply = 4
					min = -50
					max = 50
				}

				if = {
					limit = {
						scope:target_country ?= {
							is_subject = yes # For arcane reasons that I will not go into we are repeating this check here
						}
						scope:source_country ?= {
							is_subject = no
						}
						"scope:source_country.ai_army_comparison(scope:target_country.overlord)" > 0
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH_AGAINST_OVERLORD"
						value = "scope:source_country.ai_army_comparison(scope:target_country.overlord)"
						multiply = 2
						max = 50
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE_TOWARDS_OWN_OVERLORD"
					if = {
						limit = {
							has_attitude = {
								who = overlord
								attitude = rebellious
							}
						}
						value = 50
					}
					else_if = {
						limit = {
							has_attitude = {
								who = overlord
								attitude = defiant
							}
						}
						value = 25
					}
					else_if = {
						limit = {
							OR = {
								has_attitude = {
									who = overlord
									attitude = loyal
								}
								has_attitude = {
									who = overlord
									attitude = aloof
								}
							}
						}
						value = -1000
					}
				}

				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
					if = {
						limit = {
							has_attitude = {
								who = scope:source_country
								attitude = genial
							}
						}
						value = 25
					}
					if = {
						limit = {
							OR = {
								has_attitude = {
									who = scope:source_country
									attitude = protective
								}
								has_attitude = {
									who = scope:source_country
									attitude = antagonistic
								}
								has_attitude = {
									who = scope:source_country
									attitude = domineering
								}
								has_attitude = {
									who = scope:source_country
									attitude = belligerent
								}
							}
						}
						value = -1000
					}
				}
			}

			if = {
				limit = {
					NOT = { exists = scope:is_treaty_active }
					exists = scope:treaty
					scope:treaty.binding_period >= 1825
				}
				multiply = {
					desc = "DIPLOMATIC_ACCEPTANCE_BINDING_PERIOD"
					value = 1
					add = {
						value = scope:treaty.binding_period
						min = 365
						divide = 3650
					}
					max = 2
				}
			}
		}
	}
}

inputs.common/on_actions/00_code_on_actions.txt:
# For on_actions launched by the code itself.

# Fires when bookmark initialization is complete but players are still in the lobby
# At this point we do not know who the players are
# No root scope set
on_game_started = {
	effect = {}
}

# Fires after everyone enters the game from the lobby for the first time for each campaign
# At this point we DO know who the players are
# No root scope set
on_game_started_after_lobby = {
	effect = {
		# Game Rule: No Dynamic Naming
		if = {
			limit = {
				has_game_rule = no_dynamic_naming
			}
			every_state = {
				reset_state_name = yes
			    reset_hub_names = yes
			}
		}
		# The Ripper
		every_country = {
			if = {
				limit = {
					is_player = yes
				}
				random = {
					chance = 10

					set_variable = var_jack_ripper_possible
				}
			}
		}
		# Electoral Confidence
		every_country = {
			limit = {
				country_has_voting_franchise = yes
			}
			if = {
				limit = {
					OR = {
						c:GBR ?= this
						c:SWI ?= this
						c:NOR ?= this
						c:BEL ?= this
					}
				}
				set_electoral_confidence = 0.95
			}
			else_if = {
				limit = {
					OR = {
						c:FRA ?= this
						c:USA ?= this
					}
				}
				set_electoral_confidence = 0.80
			}
			else_if = {
				limit = {
					c:NET ?= this
				}
				set_electoral_confidence = 0.70
			}
			else_if = {
				limit = {
					c:BRZ ?= this
				}
				set_electoral_confidence = 0.5
			}
			else = {
				initialize_electoral_confidence = yes
			}
		}
		clear_global_variable_list = great_power_country_list
		every_country = {
			limit = {
				country_rank >= rank_value:great_power
			}
			add_to_global_variable_list = {
				name = great_power_country_list
				target = THIS
			}
		}
		set_global_variable = { # Ensures that Abraham Lincoln is not a valid leader of the Chinese Literati in 1836
			name = ruler_selector_pool_invalidation_global_var
			days = 30
		}
		if = {
			limit = {
				has_dlc_feature = ep2_content
			}
			c:JAP ?= {
				set_variable = {
					name = tenpo_gdp_goal
					value = {
						value = c:JAP.gdp
						multiply = 1.35
					}
				}
			}
		}
		c:JAP ?= {
			every_scope_character = {
				limit = {
					has_variable = daimyo_var
				}
				add_career_length = { # Important that Daimyos stay relevant until 1860 or so
					years = 10
					random_range = { 1.0 1.5 } # 10-15 years

				}
			}
			je_meiji_restoration_update_daimyos = yes
		}
	}
}

# No root scope set
on_monthly_pulse = {
	on_actions = {
		exile_pool_culling_on_action
	}
	effect = {
		every_character_in_jail = { # Music too loud? Right to jail. Right away. Driving too fast? Jail. Slow? Jail. You undercook fish? Believe it or not, jail.
			save_scope_as = prisoner_scope
			change_variable = { name = prison_time_var subtract = 1 }
			if = {
				limit = {
					NOT = {
						exists = var:prison_country
					}
				}
				kill_character = yes
			}
			else_if = {
				limit = {
					exists = var:prison_country
					var:prison_time_var <= 0
				}
				free_character_from_void = yes
				owner ?= {
					post_notification = prisoner_out_of_jail
				}
				remove_variable = prison_country
				remove_variable = prison_time_var
			}
		}

		if = {
			limit = {
				year < 1930
				NOT = { has_global_variable = germany_formed }
				c:GER ?= { is_country_alive = yes }
			}
			set_global_variable = germany_formed
		}

		# USA gets a positive/negative modifier depending on whether their capital is in Washington DC
		c:USA ?= {
			if = {
				limit = {
					NOT = { capital.state_region = s:STATE_DISTRICT_OF_COLUMBIA }
					NOT = { has_modifier = usa_capital_relocated }
				}

				add_modifier = usa_capital_relocated
				remove_modifier = usa_capital_intact
			}
			else_if = {
				limit = {
					capital.state_region = s:STATE_DISTRICT_OF_COLUMBIA
					NOT = { has_modifier = usa_capital_intact }
				}

				remove_modifier = usa_capital_relocated
				add_modifier = usa_capital_intact
			}
		}

		### Scripted country lists

		# Used to keep track of Council Republics for the purpose of the Red Scare.
		# Our thanks to Brute for reporting this.
		clear_global_variable_list = aes_country_list
		every_country = {
			limit = {
				has_law_or_variant = law_type:law_council_republic
				country_rank > rank_value:minor_power
			}
			add_to_global_variable_list = {
				name = aes_country_list
				target = THIS
			}
		}

		# Countries in the German Confederation
		clear_global_variable_list = german_confederation_country_list
		every_country_in_german_confederation = {
			limit = {
				OR = {
					country_has_primary_culture = cu:south_german
					country_has_primary_culture = cu:north_german
				}
			}
			add_to_global_variable_list = {
				name = german_confederation_country_list
				target = THIS
			}
		}

		# Great Powers
		clear_global_variable_list = great_power_country_list
		every_country = {
			limit = {
				country_rank >= rank_value:great_power
			}
			add_to_global_variable_list = {
				name = great_power_country_list
				target = THIS
			}
		}

		### Potato Famine
		if = {
			limit = {
				NOT = { has_global_variable = hungry_forties_happened }
				any_state_in_europe = {
					state_region = {
						has_harvest_condition = disease_outbreak
					}
					count >= 15
				}
			}
			set_global_variable = hungry_forties_happened
			set_global_variable = { name = hungry_forties_var days = 1095 }
		}

		# Gründerzeit JE - has to happen here in order to not kill performance
		if = {
			limit = {
				has_dlc_feature = ip3_content
				has_global_variable_list = german_confederation_country_list
			}
			if = {
				limit = {
					NOT = {
						has_global_variable = grunderzeit_possible_global_var
					}
					any_in_global_list = {
						variable = german_confederation_country_list
						has_technology_researched = mutual_funds
						any_scope_building = {
							is_building_type = building_railway
						}
						percent >= 0.75
					}
				}
				set_global_variable = grunderzeit_possible_global_var
			}
			else_if = { # If the Gründerzeit has not begun, calculate the percent of German countries which meet its requirements
				limit = {
					NOT = {
						has_global_variable = grunderzeit_possible_global_var
					}
				}
				set_global_variable = { name = grunderzeit_german_countries value = 0 }
				set_global_variable = { name = grunderzeit_countries_percent value = 0 }
					every_in_global_list = {
						variable = german_confederation_country_list
					change_global_variable = { name = grunderzeit_german_countries add = 1 }
					if = {
						limit = {
							has_technology_researched = mutual_funds
							any_scope_building = {
								is_building_type = building_railway
							}
						}
						change_global_variable = { name = grunderzeit_countries_percent add = 1 }
					}
				}
				if = {
					limit = {
						global_var:grunderzeit_german_countries != 0
					}
					change_global_variable = {
						name = grunderzeit_countries_percent
						divide = global_var:grunderzeit_german_countries
					}
				}
			}
			else_if = {
				limit = {
					OR = { # If the Gründerzeit is either ongoing or over, clear these variables.
						has_global_variable = grunderzeit_ongoing_global_var
						has_global_variable = grunderzeit_happened_global_var
					}
					has_global_variable = grunderzeit_countries_percent
					has_global_variable = grunderzeit_german_countries
				}
				remove_global_variable = grunderzeit_countries_percent
				remove_global_variable = grunderzeit_german_countries
			}
		}

		if = {
			limit = {
				exists = global_var:krakatoa_temperature_drop
				exists = global_var:krakatoa_temperature_recovery_rate
			}
			change_global_variable = {
				name = krakatoa_temperature_drop
				subtract = {
					value = global_var:krakatoa_temperature_recovery_rate
				}
			}
		}

		if = {
			limit = {
				NAND = {
					exists = c:MON
					has_global_variable = montenegro_defeat_var #do only once
				}
			}
			c:TUR ?= {
				every_scope_state = {
					limit = {
						has_modifier = raid_target
					}
					remove_modifier = raid_target
				}
			}
			set_global_variable = montenegro_defeat_var
		}

		### Checking for the Portugal is Not a Small Country achievement conditions
		if = {
			limit = {
				exists = c:POR
				c:POR ?= {
					is_player = yes
				}
			}
			### States portion
			if = {
				limit = {
					any_state_in_africa = {
						OR = {
							c:POR ?= owner
							owner ?={
								is_subject_of = c:POR
							}
						}
						count >= 12
					}
				}
				c:POR ?= {
					set_variable = achievement_portugal_is_not_a_small_country_states
				}
			}
			else = {
				if = {
					limit = {
						c:POR ?= {
							has_variable = achievement_portugal_is_not_a_small_country_states
						}
					}
					c:POR ?= {
						remove_variable = achievement_portugal_is_not_a_small_country_states
					}
				}
			}
			### Angola and Mozambique portion
			if = {
				limit = {
					any_state_in_mozambique = {
						OR = {
							c:POR ?= owner
							owner ?={
								is_subject_of = c:POR
							}
						}
						count = all
					}
					any_state_in_angola = {
						OR = {
							c:POR ?= owner
							owner ?={
								is_subject_of = c:POR
							}
						}
						count = all
					}
				}
				c:POR ?= {
					set_variable = achievement_portugal_is_not_a_small_country_angola_and_mozambique
				}
			}
			else = {
				if = {
					limit = {
						c:POR ?= {
							has_variable = achievement_portugal_is_not_a_small_country_angola_and_mozambique
						}
					}
					c:POR ?= {
						remove_variable = achievement_portugal_is_not_a_small_country_angola_and_mozambique
					}
				}
			}
			### Land Connection Portion
			if = {
				limit = { # Do not evaluate this unless this country or its subjects own all of Zambezia and East Angola
					c:POR ?= {
						OR = {
							owns_entire_state_region = STATE_ZAMBEZIA
							any_subject_or_below = {
								owns_entire_state_region = STATE_ZAMBEZIA
							}
						}
						OR = {
							owns_entire_state_region = STATE_EAST_ANGOLA
							any_subject_or_below = {
								owns_entire_state_region = STATE_EAST_ANGOLA
							}
						}
					}
				}
				evaluate_portuguese_pink_map_connection = yes
			}
			else = {
				if = {
					limit = {
						c:POR ?= {
							has_variable = achievement_portugal_is_not_a_small_country_connection
						}
					}
					c:POR ?= {
						remove_variable = achievement_portugal_is_not_a_small_country_connection
					}
				}
			}
		}
	}
}

