		}
		# for It's a Blockade! Achievement
		if = {
			limit = {
				is_player = yes
				NOT = { has_variable = its_a_blockade_happened }
				any_enemy_in_diplo_play = {
					any_scope_state = {
						is_blockaded_by = ROOT
						is_world_market_hub = yes
					    num_world_market_hub_trade_center_levels >= 100
						blockade_level >= 1
					}
				}
			}
			set_variable = its_a_blockade_happened
		}

		if = { # Nothing to see here, move along, sir.
			limit = {
				has_global_variable = frankenstein_happened_global_var
				any_company = {
					is_company_type = company_ingolstadt_electrical_company
					company_is_prosperous = yes
				}
			}
			random_scope_state = {
				create_pop = {
					culture = promethean
					size = {
						value = owner.total_population
						divide = 5000
						min = 500
						max = 100000
					}
				}
			}
		}
		if = {
			limit = {
				has_global_variable = frankenstein_happened_global_var
				any_scope_state = {
					culture_percent_state = {
						target = cu:promethean
						value >= 0.1
					}
					NOT = {
						state_region = {
							is_homeland = cu:promethean
						}
					}
				}
			}
			every_scope_state = {
				limit = {
					culture_percent_state = {
						target = cu:promethean
						value >= 0.1
					}
					NOT = {
						state_region = {
							is_homeland = cu:promethean
						}
					}
				}
				state_region = {
					add_homeland = cu:promethean
				}
			}
		}

		# Caciquismo check
		handle_possible_absent_caciquismo_variables = yes

		if = {
			limit = {
				is_ai = yes
				NOT = { is_country_type = decentralized }
			}
			ai_assemble_decree_state_maps = yes
		}

		if = {
			limit = {
				is_subject = yes
				has_modifier = modifier_not_recognized_by_spain
				top_overlord ?= {
					c:SPA ?= this
				}
			}
			remove_modifier = modifier_not_recognized_by_spain
		}

		if = {
			limit = {
				has_government_type = gov_colonial_administration_spa
				NOT = { has_modifier = modifier_reformed_captaincy_general }
			}
			add_modifier = modifier_reformed_captaincy_general
		}
		else_if = {
			limit = {
				NOT = { has_government_type = gov_colonial_administration_spa }
				has_modifier = modifier_reformed_captaincy_general
			}
			remove_modifier = modifier_reformed_captaincy_general
		}

		if = {
			limit = {
				country_has_voting_franchise = yes
				NOT = {
					modifier:country_electoral_confidence_over_time = 0
				}
				trigger_if = {
					limit = {
						modifier:country_electoral_confidence_over_time < 0
					}
					electoral_confidence > { # Can never drift to below 25%
						value = 0.25
						subtract = modifier:country_electoral_confidence_over_time
					}
				}
			}
			add_electoral_confidence = modifier:country_electoral_confidence_over_time
		}
	}
