			}
		}
		if = { # Sagrada Família Cathedral Stage 2 Complete, Stage 3 Start
			limit = {
				has_dlc_feature = ip4_content
				owner ?= {
					has_journal_entry = je_sagrada_familia
				}
				state = {
					state_region = s:STATE_CATALONIA
					has_building = building_sagrada_familia_cathedral_2
				}
			}
			owner ?= {
				trigger_event = { id = sagrada_familia.3 days = 3 }
			}
		}
		if = { # Kaiserforum Stage 1 Complete, Stage 2 Start
			limit = {
				has_dlc_feature = ip3_content
				owner ?= {
					has_journal_entry = je_kaiserforum
				}
				state = {
					state_region = s:STATE_AUSTRIA
					has_building = building_kaiserforum_1
				}
			}
			owner ?= {
				trigger_event = { id = kaiserforum.2 days = 3 }
			}
		}
		if = { # Kaiserforum Stage 2 Complete, Stage 3 Start
			limit = {
