# Fires when a goal is taken via occupation timer during a war. Goals that are not reversed before the end of the war also fire on_wargoal_enforced at the conclusion of peace.
# Root = Country
# scope:actor = the country that enforced the wargoal
# scope:target = the country the wargoal was enforced against
# scope:diplomatic_play = the relevant diplomatic play
# scope:wargoal_impact = the impact of the wargoal enforced
# scope:war_goal_enforced = the wargoal that was enforced
on_wargoal_enforced_by_timer = {
	effect = {
		scope:diplomatic_play ?= {
			post_notification = wargoal_enforced
		}
	}
}

# Fires when a goal is taken in such a manner that it cannot be reversed - from diplomatic demands, capitulation, peace deals and so on
# Also fires for all wargoals taken via occupation timer and not reversed before the end of war, at the conclusion of peace, in addition to prior on_wargoal_enforced_by_timer
# Root = Country
# scope:actor = the country that enforced the wargoal
# scope:target = the country the wargoal was enforced against
# scope:diplomatic_play = the relevant diplomatic play
# scope:wargoal_impact = the impact of the wargoal enforced
# scope:war_goal_enforced = the wargoal that was enforced
on_wargoal_enforced = {
	effect = {
		# Any war victory over the country that reneged on our inherited treaty ports settles the grudge
		if = {
			limit = {
				has_variable = wants_treaty_port_revenge_against
				var:wants_treaty_port_revenge_against ?= scope:target
			}
			remove_variable = wants_treaty_port_revenge_against
		}

		if = {
			limit = {
				OR = {
					AND = {
						has_journal_entry = je_anti_lobby_demand
						var:anti_lobby_demand_target ?= scope:target
					}
					AND = {
						has_journal_entry = je_pro_lobby_demand
						var:pro_lobby_demand_target ?= scope:target
					}
				}
			}
			set_variable = { name = enforced_wargoal_on_enemy days = 90 }
		}
		### Narrative war-end events
        if = { # Paris Commune - Commune victory event
        	limit = {
        		c:PRC ?= root
        		NOT = {
        			exists = c:FRA
        		}
        	}
        	c:PRC ?= {
				set_immune_to_revolutions = no
				change_tag = FRA
				every_scope_state = {
					limit = {
						state_region = {
							is_homeland = cu:french
						}
					}
					set_state_type = incorporated
				}
        	}
        }
		if = { # Paris Commune - France victory event
			limit = {
				c:FRA ?= root
				NOT = {
					exists = c:PRC
				}
			}
			if = {
				limit = {
					c:FRA ?= {
						is_immune_to_revolutions = yes
					}
				}
				set_immune_to_revolutions = no
			}
		}
        if = { # Ragamuffin War - Piratini victory event
        	limit = {
        		owner = {
	        		c:PNI ?= this
	        		has_variable = ragamuffin_nation_var
	        		NOT = { has_variable = won_ragamuffin_war_var }
					owns_entire_state_region = STATE_RIO_GRANDE_DO_SUL
					owns_entire_state_region = STATE_SANTA_CATARINA
				}
        	}
        	owner = {
        		set_variable = won_ragamuffin_war_var
        		trigger_event = { id = brazilian_minors.1 days = 0 popup = yes }
        	}
        }
        if = { # Ragamuffin War - Brazilian victory over Grao-Para
        	limit = {
        		owner = {
        			game_date < 1850.1.1 # Just in case.
        			NOT = {
        				has_variable = cabanagem_defeat_var
        				exists = c:PRA
        			}
	        		c:BRZ ?= this
					owns_entire_state_region = STATE_PARA
					any_scope_state = { state_region = s:STATE_AMAZONAS }
				}
        	}
        	owner = {
        		set_variable = cabanagem_defeat_var
        		trigger_event = { id = brazilian_minors.2 days = 0 popup = yes }
        	}
        }
        if = { # Ragamuffin War - Brazilian victory over Piratini
        	limit = {
        		owner = {
        			game_date < 1850.1.1 # Just in case.
        			NOT = {
        				has_variable = ragamuffin_defeat_var
        				exists = c:PNI
        			}
	        		c:BRZ ?= this
					owns_entire_state_region = STATE_RIO_GRANDE_DO_SUL
				}
        	}
        	owner = {
        		set_variable = ragamuffin_defeat_var
        		trigger_event = { id = brazilian_minors.3 days = 0 popup = yes }
        	}
        }

        if = { # recently crushed a secession
			limit = {
				scope:diplomatic_play ?= {
					is_diplomatic_play_type = dp_secession
				}
			}
			ROOT ?= {
				set_variable = {
					name = crushed_secession
					days = 90
				}
			}
		}

		if = {
			limit = {
				scope:diplomatic_play ?= {
					is_diplomatic_play_type = dp_revolution
				}
				ROOT = {
					any_subject_or_below = {
						c:EZO ?= this
						has_variable = ezo_republic_var
						has_variable = ezo_waiting_for_shogun
					}
				}
			}
			c:EZO ?= {
				top_overlord ?= {
					save_scope_as = japan_scope
				}
				country_ezo_set_up_as_colony = yes
				country_ezo_generate_next_japanese_shogun = yes
				ruler = {
					save_scope_as = shogun_scope
				}
				post_notification = ezo_tokugawa_heir_arrives
			}
		}

		if = { # Ottoman recently crushed a secession
			limit = {
				AND = {
					c:TUR ?= this
					has_journal_entry = je_great_eastern_crisis
					scope:diplomatic_play = {
						is_diplomatic_play_type = dp_secession
					}
				}
			}
			ROOT ?= {
				set_variable = {
					name = ottoman_crushed_secession
